import NavMenu from "./NavMenu";

export function Videos(){
    return(
        <div>
            <NavMenu></NavMenu>
            <br></br>
            <h1>
                Nem csak képek, hanem videókat is készítek egyes koncepciókról.
            </h1>
            <p>
                Ezek videóknak a célja, hogy a koncepció minél rövidebb idő alatt elsajátítható legyen, ezért is igyekeztem a hosszukat levágni 10 másodperc alá.
            </p>
        </div>
    );
}

export default Videos;
